impl Document {
    pub(crate) fn compare_build_action(
        &self,
        other: &Document,
        a: &BuildAction,
        b: &BuildAction,
        path: &str,
    ) -> Result<(), String> {
        self.compare_build_action_entity(other, a.base(), b.base(), path)?;
        let list_a = a.get_created_datas();
        let list_b = b.get_created_datas();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: CREATED_DATAS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.build_action_io_elements.get(*x).ok_or_else(|| {
                format!("{path}.CREATED_DATAS[{index}]: id not found in own arena")
            })?;
            let y = other.build_action_io_elements.get(*y).ok_or_else(|| {
                format!("{path}.CREATED_DATAS[{index}]: id not found in other arena")
            })?;
            self.compare_build_action_io_element(
                other,
                x,
                y,
                &format!("{path}.CREATED_DATAS[{index}]"),
            )?;
        }
        let list_a = a.get_follow_up_action_refs();
        let list_b = b.get_follow_up_action_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: FOLLOW_UP_ACTION_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.ref_types.get(*x).ok_or_else(|| {
                format!("{path}.FOLLOW_UP_ACTION_REFS[{index}]: id not found in own arena")
            })?;
            let y = other.ref_types.get(*y).ok_or_else(|| {
                format!("{path}.FOLLOW_UP_ACTION_REFS[{index}]: id not found in other arena")
            })?;
            self.compare_ref_type(
                other,
                x,
                y,
                &format!("{path}.FOLLOW_UP_ACTION_REFS[{index}]"),
            )?;
        }
        let list_a = a.get_input_datas();
        let list_b = b.get_input_datas();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: INPUT_DATAS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self
                .build_action_io_elements
                .get(*x)
                .ok_or_else(|| format!("{path}.INPUT_DATAS[{index}]: id not found in own arena"))?;
            let y = other.build_action_io_elements.get(*y).ok_or_else(|| {
                format!("{path}.INPUT_DATAS[{index}]: id not found in other arena")
            })?;
            self.compare_build_action_io_element(
                other,
                x,
                y,
                &format!("{path}.INPUT_DATAS[{index}]"),
            )?;
        }
        let list_a = a.get_modified_datas();
        let list_b = b.get_modified_datas();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: MODIFIED_DATAS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.build_action_io_elements.get(*x).ok_or_else(|| {
                format!("{path}.MODIFIED_DATAS[{index}]: id not found in own arena")
            })?;
            let y = other.build_action_io_elements.get(*y).ok_or_else(|| {
                format!("{path}.MODIFIED_DATAS[{index}]: id not found in other arena")
            })?;
            self.compare_build_action_io_element(
                other,
                x,
                y,
                &format!("{path}.MODIFIED_DATAS[{index}]"),
            )?;
        }
        let list_a = a.get_predecessor_action_refs();
        let list_b = b.get_predecessor_action_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: PREDECESSOR_ACTION_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.ref_types.get(*x).ok_or_else(|| {
                format!("{path}.PREDECESSOR_ACTION_REFS[{index}]: id not found in own arena")
            })?;
            let y = other.ref_types.get(*y).ok_or_else(|| {
                format!("{path}.PREDECESSOR_ACTION_REFS[{index}]: id not found in other arena")
            })?;
            self.compare_ref_type(
                other,
                x,
                y,
                &format!("{path}.PREDECESSOR_ACTION_REFS[{index}]"),
            )?;
        }
        if a.get_required_environment_ref() != b.get_required_environment_ref() {
            return Err(format!("{path}: REQUIRED_ENVIRONMENT_REF mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_build_action_entity(
        &self,
        other: &Document,
        a: &BuildActionEntity,
        b: &BuildActionEntity,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        let list_a = a.get_delivery_artifacts();
        let list_b = b.get_delivery_artifacts();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: DELIVERY_ARTIFACTS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.autosar_engineering_objects.get(*x).ok_or_else(|| {
                format!("{path}.DELIVERY_ARTIFACTS[{index}]: id not found in own arena")
            })?;
            let y = other.autosar_engineering_objects.get(*y).ok_or_else(|| {
                format!("{path}.DELIVERY_ARTIFACTS[{index}]: id not found in other arena")
            })?;
            self.compare_autosar_engineering_object(
                other,
                x,
                y,
                &format!("{path}.DELIVERY_ARTIFACTS[{index}]"),
            )?;
        }
        if a.get_invocation() != b.get_invocation() {
            return Err(format!("{path}: INVOCATION mismatch"));
        }
        Ok(())
    }

    pub(crate) fn compare_build_action_environment(
        &self,
        other: &Document,
        a: &BuildActionEnvironment,
        b: &BuildActionEnvironment,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        let list_a = a.get_sdgs();
        let list_b = b.get_sdgs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: SDGS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self
                .sdgs
                .get(*x)
                .ok_or_else(|| format!("{path}.SDGS[{index}]: id not found in own arena"))?;
            let y = other
                .sdgs
                .get(*y)
                .ok_or_else(|| format!("{path}.SDGS[{index}]: id not found in other arena"))?;
            self.compare_sdg(other, x, y, &format!("{path}.SDGS[{index}]"))?;
        }
        Ok(())
    }

    pub(crate) fn compare_build_action_invocator(
        &self,
        other: &Document,
        a: &BuildActionInvocator,
        b: &BuildActionInvocator,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_command() != b.get_command() {
            return Err(format!("{path}: COMMAND mismatch"));
        }
        let list_a = a.get_sdgs();
        let list_b = b.get_sdgs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: SDGS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self
                .sdgs
                .get(*x)
                .ok_or_else(|| format!("{path}.SDGS[{index}]: id not found in own arena"))?;
            let y = other
                .sdgs
                .get(*y)
                .ok_or_else(|| format!("{path}.SDGS[{index}]: id not found in other arena"))?;
            self.compare_sdg(other, x, y, &format!("{path}.SDGS[{index}]"))?;
        }
        Ok(())
    }

    pub(crate) fn compare_build_action_io_element(
        &self,
        other: &Document,
        a: &BuildActionIoElement,
        b: &BuildActionIoElement,
        path: &str,
    ) -> Result<(), String> {
        Self::compare_ar_object(a.base(), b.base(), path)?;
        if a.get_category() != b.get_category() {
            return Err(format!("{path}: CATEGORY mismatch"));
        }
        if a.get_ecuc_definition_ref() != b.get_ecuc_definition_ref() {
            return Err(format!("{path}: ECUC_DEFINITION_REF mismatch"));
        }
        if a.get_engineering_object() != b.get_engineering_object() {
            return Err(format!("{path}: ENGINEERING_OBJECT mismatch"));
        }
        if a.get_role() != b.get_role() {
            return Err(format!("{path}: ROLE mismatch"));
        }
        let list_a = a.get_sdgs();
        let list_b = b.get_sdgs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: SDGS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self
                .sdgs
                .get(*x)
                .ok_or_else(|| format!("{path}.SDGS[{index}]: id not found in own arena"))?;
            let y = other
                .sdgs
                .get(*y)
                .ok_or_else(|| format!("{path}.SDGS[{index}]: id not found in other arena"))?;
            self.compare_sdg(other, x, y, &format!("{path}.SDGS[{index}]"))?;
        }
        Ok(())
    }

    pub(crate) fn compare_build_action_manifest(
        &self,
        other: &Document,
        a: &BuildActionManifest,
        b: &BuildActionManifest,
        path: &str,
    ) -> Result<(), String> {
        self.compare_identifiable(other, a.base(), b.base(), path)?;
        let list_a = a.get_build_actions();
        let list_b = b.get_build_actions();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: BUILD_ACTIONS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.build_actions.get(*x).ok_or_else(|| {
                format!("{path}.BUILD_ACTIONS[{index}]: id not found in own arena")
            })?;
            let y = other.build_actions.get(*y).ok_or_else(|| {
                format!("{path}.BUILD_ACTIONS[{index}]: id not found in other arena")
            })?;
            self.compare_build_action(other, x, y, &format!("{path}.BUILD_ACTIONS[{index}]"))?;
        }
        let list_a = a.get_build_action_environments();
        let list_b = b.get_build_action_environments();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: BUILD_ACTION_ENVIRONMENTS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.build_action_environments.get(*x).ok_or_else(|| {
                format!("{path}.BUILD_ACTION_ENVIRONMENTS[{index}]: id not found in own arena")
            })?;
            let y = other.build_action_environments.get(*y).ok_or_else(|| {
                format!("{path}.BUILD_ACTION_ENVIRONMENTS[{index}]: id not found in other arena")
            })?;
            self.compare_build_action_environment(
                other,
                x,
                y,
                &format!("{path}.BUILD_ACTION_ENVIRONMENTS[{index}]"),
            )?;
        }
        let list_a = a.get_dynamic_action_refs();
        let list_b = b.get_dynamic_action_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: DYNAMIC_ACTION_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.ref_types.get(*x).ok_or_else(|| {
                format!("{path}.DYNAMIC_ACTION_REFS[{index}]: id not found in own arena")
            })?;
            let y = other.ref_types.get(*y).ok_or_else(|| {
                format!("{path}.DYNAMIC_ACTION_REFS[{index}]: id not found in other arena")
            })?;
            self.compare_ref_type(other, x, y, &format!("{path}.DYNAMIC_ACTION_REFS[{index}]"))?;
        }
        let list_a = a.get_start_action_refs();
        let list_b = b.get_start_action_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: START_ACTION_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.ref_types.get(*x).ok_or_else(|| {
                format!("{path}.START_ACTION_REFS[{index}]: id not found in own arena")
            })?;
            let y = other.ref_types.get(*y).ok_or_else(|| {
                format!("{path}.START_ACTION_REFS[{index}]: id not found in other arena")
            })?;
            self.compare_ref_type(other, x, y, &format!("{path}.START_ACTION_REFS[{index}]"))?;
        }
        let list_a = a.get_tear_down_action_refs();
        let list_b = b.get_tear_down_action_refs();
        if list_a.len() != list_b.len() {
            return Err(format!("{path}: TEAR_DOWN_ACTION_REFS length mismatch"));
        }
        for (index, (x, y)) in list_a.iter().zip(list_b.iter()).enumerate() {
            let x = self.ref_types.get(*x).ok_or_else(|| {
                format!("{path}.TEAR_DOWN_ACTION_REFS[{index}]: id not found in own arena")
            })?;
            let y = other.ref_types.get(*y).ok_or_else(|| {
                format!("{path}.TEAR_DOWN_ACTION_REFS[{index}]: id not found in other arena")
            })?;
            self.compare_ref_type(
                other,
                x,
                y,
                &format!("{path}.TEAR_DOWN_ACTION_REFS[{index}]"),
            )?;
        }
        Ok(())
    }

    pub(crate) fn compare_build_engineering_object(
        &self,
        other: &Document,
        a: &BuildEngineeringObject,
        b: &BuildEngineeringObject,
        path: &str,
    ) -> Result<(), String> {
        self.compare_engineering_object(other, a.base(), b.base(), path)?;
        if a.get_file_type() != b.get_file_type() {
            return Err(format!("{path}: FILE_TYPE mismatch"));
        }
        if a.get_file_type_pattern() != b.get_file_type_pattern() {
            return Err(format!("{path}: FILE_TYPE_PATTERN mismatch"));
        }
        if a.get_intended_filename() != b.get_intended_filename() {
            return Err(format!("{path}: INTENDED_FILENAME mismatch"));
        }
        if a.get_parent_category() != b.get_parent_category() {
            return Err(format!("{path}: PARENT_CATEGORY mismatch"));
        }
        if a.get_parent_short_label() != b.get_parent_short_label() {
            return Err(format!("{path}: PARENT_SHORT_LABEL mismatch"));
        }
        if a.get_short_label_pattern() != b.get_short_label_pattern() {
            return Err(format!("{path}: SHORT_LABEL_PATTERN mismatch"));
        }
        Ok(())
    }
}
